B.afF=new A.dE([B.cE,"Koperen Nacht Tripel","Goudkoper van kleur met een romige schuimkraag. Kruidig, tonen van karamel en een warme afdronk. Gevaarlijk doordrinkbaar.",u.P,"Sanne",4.5])
B.cY=new A.jk(1,"tip")
B.afY=new A.dE([B.cY,"Spoel je glas eerst koud om","Een koud gespoeld glas zorgt voor een mooiere schuimkraag en voorkomt dat je bier te snel opwarmt.",null,"BierKompas",null])
B.afB=new A.dE([B.cF,"Waarom heet het trappist?",'Een bier mag het logo "Authentic Trappist Product" alleen dragen als het onder toezicht van monniken binnen een trappistenabdij wordt gebrouwen.',null,null,null])
B.afT=new A.dE([B.cE,"Amber Kompas IPA","Fris bitter met grapefruit en dennen, maar de moutbasis houdt alles mooi in balans. Een perfect terrasbier.",null,"Joris",4])
B.afD=new A.dE([B.cY,"Schenk schuin, eindig recht","Houd het glas schuin tijdens het inschenken en zet het halverwege rechtop. Zo krijg je een kraag van ongeveer twee vingers.",null,"BierKompas",null])
B.afJ=new A.dE([B.cF,"Bock komt uit Einbeck","De naam bockbier is waarschijnlijk een verbastering van Einbeck, een Duitse stad die in de middeleeuwen bekend was om zijn sterke bier.",null,null,null])
B.afK=new A.dE([B.cE,"Donkere Molen Stout","Koffie, pure chocolade en een fluweelzachte mondvulling. Laat hem iets opwarmen, dan komt de vanille los.",null,"Fatima",4.5])
B.ag0=new A.dE([B.cY,"Niet elk bier hoort ijskoud","Pils smaakt het best rond 3 tot 5 graden, maar dubbels, tripels en stouts komen pas echt tot hun recht rond 8 tot 12 graden.",null,"BierKompas",null])
B.ag_=new A.dE([B.cF,"Hop is familie van hennep","Hop en hennep horen allebei bij de plantenfamilie Cannabaceae. Hop geeft bier bitterheid, aroma en een langere houdbaarheid.",null,null,null])
B.afS=new A.dE([B.cE,"Zomerhaven Witbier","Troebel, met citrus en koriander. Iets te zoet naar mijn smaak, maar heerlijk als het buiten 25 graden is.",u.c,"Daan",3.5])
B.afP=new A.dE([B.cY,"Bewaar flessen rechtop","Rechtop, koel en donker bewaard blijft bier langer goed. Licht kan zorgen voor een onaangename, muffe smaak.",null,"BierKompas",null])
B.afL=new A.dE([B.cF,"Spontane vergisting","Lambiek wordt spontaan vergist met wilde gisten en bacteri\xebn uit de lucht, traditioneel in de regio rond Brussel.","https://lh3.googleusercontent.com/aida-public/AB6AXuDknuVmwDTa5jB4wik1JsFZcg3HGHEguJ8tKYPIGvMOxeMgWo55nIZ92P0i_iTaZK5gCmhHDfSDDGd8HAgulU_Nt_waa4YIg1QNZCDQnGG9J70xbRh0XNaZFjxojqCPad3s7iiMSHzET5kRpj3GQcD9-hE4MuWtaKdUaP4Wkk6S1kxJhurPAITpPBmmuOIAnJ0_rU6wNjOB6JuYsppLKZZ370oFdfVTbvOpttwPVmC3aU02O1rJkSR2",null,null])
B.afG=new A.dE([B.cE,"Oude Sluis Dubbel","Rozijnen, bruine suiker en een vleugje drop. Een klassieke dubbel zonder poespas.",null,"Emma",4])
B.afM=new A.dE([B.cY,"Stout bij chocolade","De geroosterde tonen van een stout versterken een chocoladedessert. Probeer het eens met een brownie.",null,"BierKompas",null])
B.afX=new A.dE([B.cF,"Gueuze is een blend","Gueuze ontstaat door jonge en oude lambiek te mengen en op fles na te laten gisten. Daardoor krijgt het zijn bruisende, zure karakter.",null,null,null])
B.afI=new A.dE([B.cE,"Veldkers Saison","Droog, peperig en licht fruitig. Elke slok maakt dorst naar de volgende.",null,"Luuk",4.5])
B.afZ=new A.dE([B.cY,"Witbier bij vis en mosselen","De citrus- en korianderaroma's van witbier passen perfect bij vis, mosselen en frisse salades.",null,"BierKompas",null])
B.afU=new A.dE([B.cF,"Het Reinheitsgebot","In 1516 bepaalde Beieren dat bier alleen van water, gerst en hop gemaakt mocht worden. Gist werd pas later ontdekt en toegevoegd.",null,null,null])
B.afW=new A.dE([B.cE,"Koperen Nacht Blond","Honingzoet begin en een licht bittere finish. Toegankelijk, maar het mist wat karakter.",null,"Noor",3])
B.afA=new A.dE([B.cY,"Proef van licht naar zwaar","Begin een proeverij met lichte, frisse bieren en werk toe naar zware en zure bieren, zodat je smaakpapillen niet overweldigd raken.",null,"BierKompas",null])
B.afE=new A.dE([B.cF,"Donker is niet sterker","De kleur van bier komt van de mout, niet van het alcoholpercentage. Een donkere stout kan lichter zijn dan een blonde tripel.",null,null,null])
